import 'package:flutter/material.dart';

/// 程序入口：启动应用并挂载根组件
void main() => runApp(const MyApp());

/// 根组件：整个 App 的主题与首页，界面结构固定，因此用 StatelessWidget
/// 内部字段不会变化，所有子 Widget 都可以用 const 修饰

class MyApp extends StatelessWidget {
  const MyApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'StatefulWidget 入门',
      theme: ThemeData(primarySwatch: Colors.blue),
      home: const CounterPage(),
    );
  }
}

/// 计数页面：需要保存可变的计数值，因此用 StatefulWidget
/// 注意：Widget 本身依然不可变，真正的状态保存在 State 中
class CounterPage extends StatefulWidget {
  const CounterPage({super.key});

  @override
  State<CounterPage> createState() => _CounterPageState();
}

/// 与 CounterPage 配套的 State 类，_ 开头表示私有，只能在本文件使用
class _CounterPageState extends State<CounterPage> {
  /// 界面要显示的状态：计数值
  int _count = 0;

  /// 初始化：只会调用一次，适合做数据加载、监听注册
  @override
  void initState() {
    super.initState();
    debugPrint('initState 被调用，页面初始化完成');
  }

  /// 修改状态的唯一正确方式：包在 setState 中
  void _increment() {
    setState(() {
      _count++; // 在回调里修改状态，Flutter 会触发 build 重建
    });
  }

  /// 资源释放：页面销毁时调用，避免内存泄漏
  @override
  void dispose() {
    debugPrint('dispose 被调用，页面即将销毁');
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('计数器 Demo')),
      body: Center(
        child: Column(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            Text('当前计数：$_count', style: const TextStyle(fontSize: 28)),
            const SizedBox(height: 16),
            // 根据状态派生出的展示内容，同样会随 setState 刷新
            Text(_count % 2 == 0 ? '偶数' : '奇数'),
            const SizedBox(height: 24),
            // 重置按钮：演示清零操作
            ElevatedButton(
              onPressed: () => setState(() => _count = 0),
              child: const Text('清零'),
            ),
          ],
        ),
      ),
      floatingActionButton: FloatingActionButton(
        onPressed: _increment, // 点击时触发状态更新
        tooltip: '增加',
        child: const Icon(Icons.add),
      ),
    );
  }
}

