  void _increment() {
    _count++; // 没有 setState
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      body: Center(child: Text('当前计数：$_count')),
      floatingActionButton: FloatingActionButton(
        onPressed: _increment,
        child: const Icon(Icons.add),
      ),
    );
  }
}
